SELECT * FROM maintenance_and_fault WHERE upkeeprobot IN (
    SELECT botdetreg FROM robot_details 
    WHERE instdateval < CURRENT_DATE - INTERVAL '2 years'
) AND faultpredscore < 0.05;

WITH deleted_records AS (
    DELETE FROM maintenance_and_fault 
    WHERE upkeeprobot IN (
        SELECT botdetreg FROM robot_details 
        WHERE instdateval < CURRENT_DATE - INTERVAL '2 years'
    ) AND faultpredscore < 0.05
    RETURNING *
)
SELECT * FROM deleted_records;

